import java.awt.*;import java.awt.image.*;import java.io.*;import javax.imageio.ImageIO;
public class MakeIcons{public static void main(String[] args)throws Exception{BufferedImage source=ImageIO.read(new File(args[0]));for(int n:new int[]{192,512}){BufferedImage image=new BufferedImage(n,n,BufferedImage.TYPE_INT_RGB);Graphics2D g=image.createGraphics();g.setColor(Color.WHITE);g.fillRect(0,0,n,n);g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,RenderingHints.VALUE_INTERPOLATION_BICUBIC);double scale=Math.min((double)n/source.getWidth(),(double)n/source.getHeight());int w=(int)(source.getWidth()*scale),h=(int)(source.getHeight()*scale);g.drawImage(source,(n-w)/2,(n-h)/2,w,h,null);g.dispose();ImageIO.write(image,"png",new File(args[1]+"/icon-"+n+".png"));}}}
